input.command:
set -euo pipefail
SHA="5f182bf17976cac8f5457cdc1b02bb12271fef4b"
prev=""
while true; do
  resp=$(curl -sS -H "Authorization: Bearer $GITHUB_TOKEN" -H "Accept: application/vnd.github+json" \
    "https://api.github.com/repos/missingbulb/EdFringeNow/commits/$SHA/check-runs?per_page=100" || true)
  cur=$(echo "$resp" | node -e '
    let d="";process.stdin.on("data",c=>d+=c);process.stdin.on("end",()=>{
      try{const j=JSON.parse(d);const runs=j.check_runs||[];
        console.log(runs.map(r=>`${r.name}:${r.status}:${r.conclusion||"-"}`).sort().join(" "));
      }catch(e){console.log("PARSE_ERROR");}
    });')
  if [ "$cur" != "$prev" ]; then
    echo "STATE $cur"
    prev="$cur"
  fi
  if echo "$resp" | node -e '
    let d="";process.stdin.on("data",c=>d+=c);process.stdin.on("end",()=>{
      try{const j=JSON.parse(d);const runs=j.check_runs||[];
        if(runs.length>0 && runs.every(r=>r.status==="completed")) process.exit(0);
      }catch(e){}
      process.exit(1);
    });'; then
    echo "ALL_CONCLUDED $cur"
    break
  fi
  sleep 20
done

